Lemma round8_le_page_grant : forall old n,
  (0 <= old)%Z -> (0 <= n)%Z ->
  (old mod page_size = 0)%Z ->
  ((((n + 7) / 8) * 8) <= page_round_up_Z (old + n) - old)%Z.
Proof.
